/** Private object storage for listing photos, verification documents and report evidence. */

export type StoredObject = { body: Buffer; contentType: string };

export interface ObjectStorage {
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  /** Returns null when the object does not exist. */
  get(key: string): Promise<StoredObject | null>;
  /** Deleting a missing object is not an error. */
  delete(key: string): Promise<void>;
}

const SEGMENT = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

/**
 * Keys are generated by the server (see newStorageKey), never taken from user input, but
 * every driver still checks them so a bug can never read or write outside the store.
 */
export function assertSafeKey(key: string): void {
  const ok =
    key.length > 0 &&
    key.length <= 512 &&
    !key.startsWith("/") &&
    key.split("/").every((s) => SEGMENT.test(s) && s !== "." && s !== ".." && !s.includes(".."));
  if (!ok) throw new Error(`Unsafe storage key: ${JSON.stringify(key)}`);
}

const CONTENT_TYPES: Record<string, string> = {
  webp: "image/webp",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  png: "image/png",
  pdf: "application/pdf",
};

/** Content type implied by a key's extension (keys always carry one). */
export function contentTypeForKey(key: string): string {
  const ext = key.slice(key.lastIndexOf(".") + 1).toLowerCase();
  return CONTENT_TYPES[ext] ?? "application/octet-stream";
}
